package javaprojects;

import java.util.ArrayList;

public class App {

    public static void main(String[] args) {

        FuzzyListGenerator generator = new FuzzyListGenerator();
        FuzzyFinder finder = new FuzzyFinder();

        ArrayList<Fuzzy> sortedList = generator.sortedRainbowFuzzies();
        ArrayList<Fuzzy> randomList = generator.randomizedRainbowFuzzies();

         
        int linearSorted = finder.linearSearch(sortedList);
        int linearRandom = finder.linearSearch(randomList);

       
        int binarySorted = finder.binarySearch(sortedList);
        int binaryRandom = finder.binarySearch(randomList);

        System.out.println("\nLinear Search: ");
        System.out.println("Sorted list gold index: " + linearSorted);
        System.out.println("Randomized list gold index: " + linearRandom);

        System.out.println();

        System.out.println("Binary Search: ");
        System.out.println("Sorted list gold index: " + binarySorted);
        System.out.println("Randomized list gold index: " + binaryRandom);
    }
}